import { For, onCleanup, onMount } from 'solid-js';
import {
  Carousel,
  CarouselContext,
  CarouselControl,
  CarouselIndicator,
  CarouselIndicatorGroup,
  CarouselItem,
  CarouselItemGroup,
  CarouselNextTrigger,
  CarouselPrevTrigger,
} from '@/registry/solid/ui/carousel';
import styles from './autoplay-gallery.module.css';

const slides = [
  {
    id: 'workspaces',
    category: 'Workspaces',
    title: 'Space to make ideas happen',
    description: 'Quiet rooms, shared tables, and a place to reset between meetings.',
    src: 'https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=1600&q=85',
    alt: 'A bright office with tables, chairs, and plants.',
  },
  {
    id: 'outdoors',
    category: 'Outdoors',
    title: 'Find your next wide-open weekend',
    description: 'A little fresh air, a long trail, and views worth slowing down for.',
    src: 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1600&q=85',
    alt: 'Snow-covered mountains under a clear sky.',
  },
  {
    id: 'wellbeing',
    category: 'Wellbeing',
    title: 'Make room for feeling better',
    description: 'Thoughtful care and small rituals that keep the everyday in balance.',
    src: 'https://images.unsplash.com/photo-1540555700478-4be289fbecef?auto=format&fit=crop&w=1600&q=85',
    alt: 'A calm spa room with warm light and a treatment bed.',
  },
  {
    id: 'community',
    category: 'Community',
    title: 'The good part is doing it together',
    description: 'Make time for the people, places, and events that bring energy back.',
    src: 'https://images.unsplash.com/photo-1517457373958-b7bdd4587205?auto=format&fit=crop&w=1600&q=85',
    alt: 'Friends enjoying an outdoor gathering at sunset.',
  },
];

function ResumeAutoplayWhenVisible(props: { onVisible: () => void }) {
  const resume = () => {
    if (document.visibilityState === 'visible') props.onVisible();
  };

  onMount(() => document.addEventListener('visibilitychange', resume));
  onCleanup(() => document.removeEventListener('visibilitychange', resume));

  return null;
}

export function AutoplayGallery() {
  return (
    <Carousel
      aria-label="Featured experiences"
      autoplay={{ delay: 3500 }}
      class={styles.gallery}
      loop
      padding="var(--autoplay-gallery-padding, var(--moduix-spacing-8))"
      slideCount={slides.length}
      slidesPerPage={1.12}
      spacing="var(--autoplay-gallery-spacing, var(--moduix-spacing-4))"
    >
      <CarouselContext>
        {(api) => (
          <>
            <ResumeAutoplayWhenVisible onVisible={api().play} />
            <div class={styles.viewport}>
              <CarouselItemGroup
                class={styles.itemGroup}
                onTouchStart={api().pause}
                onWheel={(event) => {
                  if (event.deltaX !== 0) api().pause();
                }}
              >
                <For each={slides}>
                  {(slide, index) => (
                    <CarouselItem
                      class={styles.item}
                      data-active={api().page === index() ? '' : undefined}
                      index={index()}
                      snapAlign="center"
                    >
                      <img class={styles.image} src={slide.src} alt={slide.alt} />
                      <div class={styles.copy}>
                        <span class={styles.category}>{slide.category}</span>
                        <h2 class={styles.title}>{slide.title}</h2>
                        <p class={styles.description}>{slide.description}</p>
                      </div>
                    </CarouselItem>
                  )}
                </For>
              </CarouselItemGroup>

              <CarouselControl class={styles.control}>
                <CarouselPrevTrigger
                  class={styles.prevTrigger}
                  onClick={() => requestAnimationFrame(api().play)}
                />
                <CarouselNextTrigger
                  class={styles.nextTrigger}
                  onClick={() => requestAnimationFrame(api().play)}
                />
              </CarouselControl>
            </div>
          </>
        )}
      </CarouselContext>

      <CarouselContext>
        {(api) => (
          <CarouselIndicatorGroup class={styles.indicatorGroup}>
            <For each={api().pageSnapPoints}>
              {(_, index) => (
                <CarouselIndicator
                  class={styles.indicator}
                  data-playing={api().isPlaying ? '' : undefined}
                  index={index()}
                  onClick={() => requestAnimationFrame(api().play)}
                />
              )}
            </For>
          </CarouselIndicatorGroup>
        )}
      </CarouselContext>
    </Carousel>
  );
}

.gallery {
  width: min(100%, 68rem);
}

.viewport {
  position: relative;
  overflow: clip;
}

.itemGroup {
  padding-block: var(--moduix-spacing-3);
}

.item {
  position: relative;
  min-height: clamp(22rem, 48vw, 32rem);
  overflow: hidden;
  border-radius: var(--moduix-radius-xl);
  opacity: 0.58;
  transform: scale(0.96);
  transition:
    opacity var(--moduix-transition-slow),
    transform var(--moduix-transition-slow);

  &[data-active] {
    opacity: 1;
    transform: scale(1);
  }

  &::before {
    position: absolute;
    z-index: 1;
    inset: 35% 0 0;
    border-radius: inherit;
    background: linear-gradient(
      to top,
      color-mix(in oklab, var(--moduix-color-foreground) 68%, transparent),
      transparent
    );
    content: '';
    pointer-events: none;
    backdrop-filter: blur(1rem);
    mask-image: linear-gradient(to top, black 45%, transparent);
  }
}

.image {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: inherit;
  object-fit: cover;
}

.copy {
  position: absolute;
  z-index: 1;
  inset-inline: var(--moduix-spacing-5);
  inset-block-end: var(--moduix-spacing-5);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: var(--moduix-spacing-1);
  max-width: min(34rem, calc(100% - var(--moduix-spacing-10)));
  color: white;
}

.category {
  color: color-mix(in oklab, white 78%, transparent);
  font-size: var(--moduix-text-xs);
  font-weight: var(--moduix-weight-semibold);
  letter-spacing: 0.08em;
  line-height: var(--moduix-line-height-text-xs);
  text-transform: uppercase;
}

.title,
.description {
  margin: 0;
  color: inherit;
}

.title {
  max-width: 22ch;
  font-size: clamp(var(--moduix-text-xl), 3vw, var(--moduix-text-3xl));
  line-height: 1.15;
  text-wrap: balance;
}

.description {
  max-width: 52ch;
  color: color-mix(in oklab, white 84%, transparent);
  font-size: var(--moduix-text-sm);
  line-height: var(--moduix-line-height-text-sm);
  text-wrap: pretty;
}

.control {
  position: absolute;
  z-index: 1;
  inset: 0;
  justify-content: space-between;
  padding-inline: var(--moduix-spacing-4);
  pointer-events: none;
}

.prevTrigger,
.nextTrigger {
  pointer-events: auto;
  box-shadow: var(--moduix-shadow-md);
}

.indicatorGroup {
  margin-block-start: var(--moduix-spacing-2);
}

.indicator {
  position: relative;
  overflow: visible;
  background-color: color-mix(
    in oklab,
    var(--moduix-color-muted) 90%,
    var(--moduix-color-foreground)
  );
  opacity: 1;

  &[data-current] {
    background-color: color-mix(
      in oklab,
      var(--moduix-color-muted) 90%,
      var(--moduix-color-foreground)
    );
  }

  &::before {
    position: absolute;
    inset-block: 0;
    inset-inline-start: 0;
    width: 0;
    background-color: var(--moduix-carousel-indicator-bg-current, var(--moduix-color-primary));
    border-radius: inherit;
    content: '';
  }

  &::after {
    position: absolute;
    inset-block: calc(-1 * var(--moduix-spacing-2));
    inset-inline: 0;
    content: '';
  }

  &[data-current]::before {
    width: 100%;
  }

  &[data-current][data-playing]::before {
    animation: autoplay-gallery-progress 3.5s linear forwards;
  }
}

@keyframes autoplay-gallery-progress {
  from {
    width: 0;
  }

  to {
    width: 100%;
  }
}

@media (max-width: 40rem) {
  .gallery {
    --autoplay-gallery-padding: var(--moduix-spacing-5);
    --autoplay-gallery-spacing: var(--moduix-spacing-2);
  }

  .item {
    min-height: 0;
    aspect-ratio: 5 / 4;
  }

  .copy {
    inset-inline: var(--moduix-spacing-3);
    inset-block-end: var(--moduix-spacing-3);
    max-width: calc(100% - var(--moduix-spacing-6));
  }

  .title {
    font-size: var(--moduix-text-md);
    line-height: var(--moduix-line-height-text-md);
  }

  .description {
    display: none;
  }

  .control {
    padding-inline: var(--moduix-spacing-2);
  }
}

@media (prefers-reduced-motion: reduce) {
  .item {
    transition: none;
  }

  .indicator[data-current]::before {
    animation: none;
    width: 100%;
  }
}
